//! Canonical retained UNIQUE policy rows, not language declarations or syntax.
use std::{borrow::Borrow,io};use crate::{captured_generator_budget::Budget,reactive_reads_native::Failure};
pub(crate) struct Map<K,V>{rows:Vec<(K,V)>}pub(crate) struct Set<K>{rows:Vec<K>}
impl<K,V> Default for Map<K,V>{fn default()->Self{Self{rows:Vec::new()}}}impl<K> Default for Set<K>{fn default()->Self{Self{rows:Vec::new()}}}
fn empty<T>(count:usize,budget:&Budget,poll:&mut dyn FnMut()->io::Result<()>)->Result<Vec<T>,Failure>{poll()?;if count==0{return Ok(Vec::new())}let bytes=count.checked_mul(std::mem::size_of::<T>()).and_then(|n|n.checked_mul(4)).and_then(|n|n.checked_add(64)).ok_or_else(||{budget.deny();Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,"policy fact row capacity overflow"))})?;budget.charge(bytes).map_err(|message|Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,message)))?;let mut rows=Vec::new();rows.try_reserve_exact(count).map_err(|actual|{budget.deny();Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,actual))})?;if rows.capacity().checked_mul(std::mem::size_of::<T>()).is_none_or(|n|n>bytes){budget.deny();return Err(Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,"policy fact allocator exceeds preadmission")))}Ok(rows)}
impl<K:Ord,V> Map<K,V>{
 pub fn freeze(rows:impl ExactSizeIterator<Item=(K,V)>,budget:&Budget,poll:&mut dyn FnMut()->io::Result<()>)->Result<Self,Failure>{let mut out=empty(rows.len(),budget,poll)?;for row in rows{poll()?;out.push(row)}out.sort_unstable_by(|a,b|a.0.cmp(&b.0));poll()?;Ok(Self{rows:out})}
 pub fn freeze_values<T>(rows:impl ExactSizeIterator<Item=(K,T)>,budget:&Budget,poll:&mut dyn FnMut()->io::Result<()>,mut value:impl FnMut(T,&Budget,&mut dyn FnMut()->io::Result<()>)->Result<V,Failure>)->Result<Self,Failure>{let mut out=empty(rows.len(),budget,poll)?;for(key,item)in rows{poll()?;out.push((key,value(item,budget,poll)?));}out.sort_unstable_by(|a,b|a.0.cmp(&b.0));poll()?;Ok(Self{rows:out})}
 pub fn len(&self)->usize{self.rows.len()}
 pub fn get<Q:Ord+?Sized>(&self,key:&Q)->Option<&V>where K:Borrow<Q>{self.rows.binary_search_by(|(stored,_)|stored.borrow().cmp(key)).ok().map(|index|&self.rows[index].1)}
 pub fn contains_key<Q:Ord+?Sized>(&self,key:&Q)->bool where K:Borrow<Q>{self.get(key).is_some()}
 pub fn iter(&self)->impl ExactSizeIterator<Item=(&K,&V)>{self.rows.iter().map(|(key,value)|(key,value))}
 pub fn keys(&self)->impl ExactSizeIterator<Item=&K>{self.rows.iter().map(|row|&row.0)}
 pub fn values(&self)->impl ExactSizeIterator<Item=&V>{self.rows.iter().map(|row|&row.1)}
}
impl<K:Ord> Set<K>{pub fn len(&self)->usize{self.rows.len()}pub fn freeze(rows:impl ExactSizeIterator<Item=K>,budget:&Budget,poll:&mut dyn FnMut()->io::Result<()>)->Result<Self,Failure>{let mut out=empty(rows.len(),budget,poll)?;for row in rows{poll()?;out.push(row)}out.sort_unstable();poll()?;Ok(Self{rows:out})}pub fn contains<Q:Ord+?Sized>(&self,key:&Q)->bool where K:Borrow<Q>{self.rows.binary_search_by(|stored|stored.borrow().cmp(key)).is_ok()}pub fn iter(&self)->impl ExactSizeIterator<Item=&K>{self.rows.iter()}}
pub(crate) trait Storage{fn storage(&self,visit:&mut dyn FnMut(usize,usize));}
impl Storage for String{fn storage(&self,visit:&mut dyn FnMut(usize,usize)){if self.capacity()!=0{visit(self.as_ptr()as usize,self.capacity())}}}
impl Storage for bool{fn storage(&self,_:&mut dyn FnMut(usize,usize)){}}
impl Storage for usize{fn storage(&self,_:&mut dyn FnMut(usize,usize)){}}
impl<A:Storage,B:Storage> Storage for(A,B){fn storage(&self,visit:&mut dyn FnMut(usize,usize)){self.0.storage(visit);self.1.storage(visit)}}
impl<T:Storage> Storage for Option<T>{fn storage(&self,visit:&mut dyn FnMut(usize,usize)){if let Some(value)=self{value.storage(visit)}}}
impl<T:Storage> Storage for Vec<T>{fn storage(&self,visit:&mut dyn FnMut(usize,usize)){if self.capacity()!=0{visit(self.as_ptr()as usize,self.capacity().checked_mul(std::mem::size_of::<T>()).unwrap_or(usize::MAX));}for value in self{value.storage(visit)}}}
impl<K:Storage,V:Storage> Storage for Map<K,V>{fn storage(&self,visit:&mut dyn FnMut(usize,usize)){self.rows.storage(visit)}}
impl<K:Storage> Storage for Set<K>{fn storage(&self,visit:&mut dyn FnMut(usize,usize)){self.rows.storage(visit)}}
#[cfg(test)]mod tests{use super::*;#[test]fn canonical_policy_map_moves_strings_and_preserves_exact_lookup_without_node_retention(){let text=String::from("retained");let pointer=text.as_ptr();let original=std::collections::HashMap::from([(String::from("z"),text),(String::from("a"),String::from("first"))]);let budget=Budget::new(65536).unwrap();let rows=Map::freeze(original.into_iter(),&budget,&mut||Ok(())).unwrap();assert_eq!(rows.get("z").unwrap().as_ptr(),pointer);assert_eq!(rows.keys().map(String::as_str).collect::<Vec<_>>(),vec!["a","z"]);assert_eq!(rows.get("missing"),None);let mut count=0;rows.storage(&mut|_,bytes|{assert!(bytes>0);count+=1;});assert_eq!(count,5);}#[test]fn canonical_policy_map_denies_before_rows_and_preserves_actual_checkpoint_io(){let fixed=std::mem::size_of::<Budget>()+2*std::mem::size_of::<usize>();let tiny=Budget::new(fixed).unwrap();let result=Map::freeze(std::iter::once(("key".to_owned(),"value".to_owned())),&tiny,&mut||Ok(()));assert!(matches!(result,Err(Failure::Operational(ref actual))if actual.kind()==io::ErrorKind::OutOfMemory));assert!(tiny.denied());let healthy=Budget::new(65536).unwrap();let result=Map::freeze(std::iter::once(("key".to_owned(),"value".to_owned())),&healthy,&mut||Err(io::Error::from_raw_os_error(1450)));let Err(Failure::Operational(actual))=result else{panic!("actual IO")};assert_eq!(actual.raw_os_error(),Some(1450));}}
